#include <stdio.h>
#include <string.h>

int L, C;
int black[6][6];
int inA[6][6];
int matchR[36];

int dr[4] = {-1, 1, 0, 0};
int dc[4] = {0, 0, -1, 1};

int dfs(int u, int vis[]) {
    int r = u / C;
    int c = u % C;

    for (int i = 0; i < 4; i++) {
        int nr = r + dr[i];
        int nc = c + dc[i];

        if (nr < 0 || nr >= L || nc < 0 || nc >= C) continue;
        if (!inA[nr][nc]) continue;

        if (((nr + nc) & 1) == 0) continue;

        int v = nr * C + nc;
        if (vis[v]) continue;

        vis[v] = 1;
        if (matchR[v] == -1 || dfs(matchR[v], vis)) {
            matchR[v] = u;
            return 1;
        }
    }

    return 0;
}

int main() {
    int P;

    scanf("%d %d", &L, &C);
    scanf("%d", &P);

    memset(black, 0, sizeof(black));

    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x - 1][y - 1] = 1;
    }

    memset(inA, 0, sizeof(inA));

    int total = 0;

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (black[r][c]) continue;

            int ok = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                    ok = 1;
                    break;
                }
            }

            if (ok) {
                inA[r][c] = 1;
                total++;
            }
        }
    }

    memset(matchR, -1, sizeof(matchR));

    int matching = 0;

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (inA[r][c] && ((r + c) & 1) == 0) {
                int vis[36] = {0};
                if (dfs(r * C + c, vis)) {
                    matching++;
                }
            }
        }
    }

    printf("%d\n", total - matching);

    return 0;
}
